31	  /* eslint-disable @typescript-eslint/no-explicit-any */
32	  app
33	    .get('/', (c: any) => c.text('Hi'))
34	    .post('/json', (c: any) => c.req.json().then(c.json))
35	    .get('/id/:id', (c: any) => {
36	      const id = c.req.param('id')
37	      const name = c.req.query('name')
38	      c.header('x-powered-by', 'benchmark')
39	      return c.text(`${id} ${name}`)
40	    })
41	    .get('/user', (c: any) => c.json({ id: 123, name: 'Alice', roles: ['admin', 'editor'] }))
42	    .use('/mw/*', async (_c: any, next: any) => {
43	      await next()
44	    })
45	    .get('/mw/hello', (c: any) => c.text('mw'))
46	  return app
47	}
