53	const user = new Request('http://localhost/user')
54	const mw = new Request('http://localhost/mw/hello')
55	
56	let sink: unknown
57	
58	const caseFilter = process.env.HONO_CASE
59	
60	const allCases: [string, (app: any) => Promise<unknown>][] = [
61	  ['ping GET /', (app) => app.fetch(ping)],
62	  ['query GET /id/1?name=bun', (app) => app.fetch(query)],
63	  ['json GET /user', (app) => app.fetch(user)],
64	  ['middleware GET /mw/hello', (app) => app.fetch(mw)],
65	  [
66	    'body POST /json',
67	    (app) =>
68	      app.fetch(
69	        new Request('http://localhost/json', {
70	          method: 'POST',
71	          headers: { 'content-type': 'application/json' },
72	          body: '{"hello":"world"}',
73	        })
74	      ),
75	  ],
76	]
