83	// Warm up before registering benches: the first fetch builds the router
84	// lazily (>500µs), which makes mitata skip batching for the first bench.
85	for (const [, fn] of allCases) {
86	  sink = await fn(app)
87	}
88	
89	for (const [name, fn] of cases) {
90	  bench(name, async () => {
91	    sink = await fn(app)
92	  })
93	}
