95	if (asJson) {
96	  // Force batching on: without it, each iteration is timed individually at
97	  // timer granularity (~41ns on Apple Silicon), which is too coarse here.
98	  const results: Record<string, { avg: number; min: number; p75: number }> = {}
99	  for (const [name, fn] of cases) {
100	    const stats = await measure(
101	      async () => {
102	        sink = await fn(app)
103	      },
104	      {
105	        warmup_threshold: Number.MAX_SAFE_INTEGER,
106	        batch_threshold: Number.MAX_SAFE_INTEGER,
107	      }
